style.css:
body {
  background: url("https://i.imgur.com/yourBackground.jpg") no-repeat center center fixed !important;
  background-size: cover !important; /* makes it stretch to fit screen */
}
body, p, span, div {
  color: #000000 !important; /* pure black */
}
a {
  color: #006400 !important; /* dark green */
}
::selection {
  background: #006400; /* dark green background */
  color: #ffffff;      /* white text on highlight */
}
h1, h2, h3, h4, h5, h6 {
  color: #006400 !important; /* dark green */
}
